function parse(messageType, args) {
        const options = getOptions(messageType);
        /** Interpreter */
        if (typeof options.interpreter === "function") {
            for (const index in args) {
                /** Let string be without additional ' ' */
                if (typeof args[index] === "string") {
                    continue;
                }
                args[index] = options.interpreter(args[index]);
            }
        }
        /** Label */
        if (options.labels) {
            args.unshift(`[${messageType.toUpperCase()}]`);
        }
        /** Timestamp */
        if (options.timestamp) {
            switch (typeof options.timestamp) {
                case "boolean":
                    args.unshift(`[${new Date().toLocaleString()}]`);
                    break;
                case "string":
                    args.unshift(`[${moment().format(options.timestamp)}]`);
                    break;
                default:
                    throw new Error(`Invalid timestamp type (${typeof options.timestamp}). Should be (boolean | string)`);
            }
        }
        return args.join(" ");
    }

public ResultSetFuture putAsync(Locator locator, long collectionTime, Rollup rollup, Granularity granularity, int ttl) {

        Session session = DatastaxIO.getSession();

        // we use batch statement here in case sub classes
        // override the addRollupToBatch() and provide
        // multiple statements
        BatchStatement batch = new BatchStatement();
        addRollupToBatch(batch, locator, rollup, collectionTime, granularity, ttl);

        Collection<Statement> statements = batch.getStatements();
        if ( statements.size() == 1 ) {
            Statement oneStatement = statements.iterator().next();
            return session.executeAsync(oneStatement);
        } else {
            LOG.debug(String.format("Using BatchStatement for %d statements", statements.size()));
            return session.executeAsync(batch);
        }
    }

