            if (state.getState().equals(WorkPanelState.NOT_SAVED))
            {
                // Save the work
                saveWork();
            }
        }
        else if ("Cancel".equals(action))
        {
            // Check if the state is NOT_SAVED
            if (state.getState().equals(WorkPanelState.NOT_SAVED))
            {
