    'keyId="' + keyId + '", ' +
    'headers="date digest", ' +
    'algorithm="rsa-sha256", ' +
    'signature="' +
    signMsg(combine([ 'date', 'digest' ], headers), key, 'RSA-SHA256')
      .toString('base64') + '"';

  return headers;
}

