def get_median(values, kdd):
  """
  Given an unsorted list of numeric values, return median value (as a float).
  Note that in the case of even-length lists of values, we apply the value to
  the left of the center to be the median (such that the median can only be
  a value from the list of values).
  Eg: get_median([1,2,3,4]) == 2, not 2.5.
  """

  if not values:
    raise Exception("Cannot calculate median of list with no values!")

  sorted_values = deepcopy(values)
  sorted_values.sort() # Not calling `sorted` b/c `sorted_values` may not be list.

  if kdd:
    return sorted_values[len(values)//2]
  else:
    if len(values) % 2 == 0:
      return sorted_values[len(values)//2-1]
    else:
      return sorted_values[len(values)//2]

function getUpdateInfo(update) {
    /** Is it chosen inline or edited message/post */
    let isChosen = false;
    let isEdited = false;

    /** Raw and formatted names of update */
    let original = '';
    let name = '';

    if (update.message) {
        name = 'message';
        original = 'message';
    } else if (update.edited_message) {
        isEdited = true;
        original = 'edited_message';
        name = 'message';
    } else if (update.channel_post) {
        original = 'channel_post';
        name = 'post';
    } else if (update.edited_channel_post) {
        isEdited = true;
        original = 'edited_channel_post';
        name = 'post';
    } else if (update.inline_query) {
        original = 'inline_query';
        name = 'inline';
    } else if (update.chosen_inline_result) {
        isChosen = true;
        original = 'chosen_inline_result';
        name = 'inline';
    } else if (update.callback_query) {
        original = 'callback_query';
        name = 'callback';
    }

    return { isChosen, isEdited, original, name };
}

