public function getBodyParams()
    {
        if ($this->_bodyParams === null) {
            $reactMethod = strtoupper($this->reactRequest->getMethod());
            $reactBody = $this->reactRequest->getParsedBody();
            if ($reactMethod === 'POST' && isset($reactBody[$this->methodParam])) {
                $this->_bodyParams = $reactBody;
                unset($this->_bodyParams[$this->methodParam]);
                return $this->_bodyParams;
            }

            $rawContentType = $this->getContentType();
            if (($pos = strpos($rawContentType, ';')) !== false) {
                // e.g. text/html; charset=UTF-8
                $contentType = substr($rawContentType, 0, $pos);
            } else {
                $contentType = $rawContentType;
            }

            if (isset($this->parsers[$contentType])) {
                $parser = Reaction::create($this->parsers[$contentType]);
                if (!($parser instanceof RequestParserInterface)) {
                    throw new InvalidConfigException("The '$contentType' request parser is invalid. It must implement the Reaction\\Web\\RequestParserInterface.");
                }
                $this->_bodyParams = $parser->parse($this->getRawBody(), $rawContentType);
            } elseif (isset($this->parsers['*'])) {
                $parser = Reaction::create($this->parsers['*']);
                if (!($parser instanceof RequestParserInterface)) {
                    throw new InvalidConfigException('The fallback request parser is invalid. It must implement the Reaction\\Web\\RequestParserInterface.');
                }
                $this->_bodyParams = $parser->parse($this->getRawBody(), $rawContentType);
            } elseif ($this->getMethod() === 'POST') {
                // PHP has already parsed the body so we have all params in $_POST
                $this->_bodyParams = $reactBody;
            } else {
                $this->_bodyParams = [];
                mb_parse_str($this->getRawBody(), $this->_bodyParams);
            }
        }

        return $this->_bodyParams;
    }

function clearCache() {
  var overflow = frames.length - MAX_FRAMES_LENGTH;
  overflow > 0 && frames.splice(0, overflow + 60);
  var len = ids.length;
  if (len <= MAX_LENGTH) {
    return;
  }

  var now = Date.now();
  var _ids = [];
  var preserveLen = len;
  overflow = -1;
  if (len >= OVERFLOW_LENGTH) {
    overflow = len - MAX_CACHE_SIZE;
    preserveLen = len - PRESERVE_LEN;
  }
  for (var i = 0; i < len; i++) {
    var id = ids[i];
    var curData = reqData[id];
    if (i > overflow && 
      (i >= preserveLen || 
        (curData.endTime ? now - curData.endTime < CACHE_TIME : now - curData.startTime < CACHE_TIMEOUT))) {
      if (curData.endTime && curData.abort) {
        delete curData.abort;
      }  
      _ids.push(id);
    } else {
      delete reqData[id];
    }
  }
  ids = _ids;
}

